//! ADR 0099 stage-0 L3-A concurrency repro harness (read-only audit artifact).
//! Usage: repro <off-by-one|retry-clobber|version-reset|deferred|hold|write>
use pony_agent_core::agent::session::{
    SeparateTraceTableMode, SessionBackend, SessionState, SessionStore,
};
use pony_agent_core::agent::sqlite_session::SqliteSessionBackend;
use std::path::PathBuf;

fn backend(db: &PathBuf) -> SqliteSessionBackend {
    SqliteSessionBackend::new_with_trace_mode(db.clone(), SeparateTraceTableMode::WriteSeparate)
}

fn hist_ver(db: &PathBuf, id: &str) -> (usize, i64) {
    let conn = rusqlite::Connection::open(db).unwrap();
    let data: String = conn
        .query_row("SELECT session_data FROM sessions WHERE conversation_id=?1", [id], |r| r.get(0))
        .unwrap();
    let v: serde_json::Value = serde_json::from_str(&data).unwrap();
    let ver: i64 = conn
        .query_row("SELECT version FROM sessions WHERE conversation_id=?1", [id], |r| r.get(0))
        .unwrap();
    (v.get("history").and_then(|h| h.as_array()).map(|a| a.len()).unwrap_or(0), ver)
}

fn tmp(tag: &str) -> PathBuf {
    let d = std::env::temp_dir().join(format!("l3a-{tag}-{}", std::process::id()));
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    match mode.as_str() {
        // F3: advance_versions() uses the stale `known` map -> every later full commit is StaleVersion.
        "off-by-one" => {
            let dir = tmp("oob");
            let db = dir.join("sessions.db");
            let mut s = SessionStore::with_backend(Box::new(backend(&db)));
            s.append_turn(Some("s1"), "q", "a", None, Vec::new());
            for i in 0..3 {
                let ws = dir.join(format!("ws{i}"));
                std::fs::create_dir_all(&ws).unwrap();
                eprintln!("--- full commit #{i} ---");
                s.create_workspace(&format!("w{i}"), ws.to_str().unwrap()).unwrap();
                eprintln!("after #{i}: (history,version)={:?}", hist_ver(&db, "s1"));
            }
        }
        // F2: CAS detects the conflict, then the retry re-submits the stale snapshot and clobbers it.
        "retry-clobber" => {
            let dir = tmp("clobber");
            let db = dir.join("sessions.db");
            let mut a = SessionStore::with_backend(Box::new(backend(&db)));
            a.append_turn(Some("s1"), "q1", "a1", None, Vec::new());
            let mut b = SessionStore::with_backend(Box::new(backend(&db)));
            eprintln!("B snapshot = {:?}", hist_ver(&db, "s1"));
            a.append_turn(Some("s1"), "q2", "a2", None, Vec::new());
            eprintln!("after A turn2 = {:?}", hist_ver(&db, "s1"));
            let ws = dir.join("ws");
            std::fs::create_dir_all(&ws).unwrap();
            b.create_workspace("w", ws.to_str().unwrap()).unwrap();
            eprintln!("AFTER B full commit = {:?} (2 == A turn2 silently lost)", hist_ver(&db, "s1"));
        }
        // F4: the production upsert_session fallback resets sessions.version to 0 (INSERT OR REPLACE
        // without the version column) -> an old snapshot with expected=0 passes CAS.
        "version-reset" => {
            let dir = tmp("reset");
            let db = dir.join("sessions.db");
            let mut a = SessionStore::with_backend(Box::new(backend(&db)));
            a.append_turn(Some("s1"), "q1", "a1", None, Vec::new());
            let r = backend(&db);
            let stale = r.load_store().expect("snapshot with expected version 0");
            let ws = dir.join("ws");
            std::fs::create_dir_all(&ws).unwrap();
            a.create_workspace("w", ws.to_str().unwrap()).unwrap();
            a.append_turn(Some("s1"), "q2", "a2", None, Vec::new());
            eprintln!("before fallback = {:?}", hist_ver(&db, "s1"));
            let u = backend(&db);
            let st: SessionState = serde_json::from_str(
                r#"{"conversationId":"s1","summary":"","history":[],"turnCount":0,"lastReferencedFile":null}"#,
            ).unwrap();
            assert!(u.upsert_session("s1", &st));
            eprintln!("after upsert_session fallback = {:?}", hist_ver(&db, "s1"));
            eprintln!("stale snapshot => {:?}", r.commit_boundary(&stale));
            eprintln!("FINAL = {:?} (2 == stale snapshot overwrote 4 msgs)", hist_ver(&db, "s1"));
        }
        // F1: BEGIN DEFERRED read-then-write; a concurrent commit between read and write => Failed.
        "deferred" => {
            let dir = tmp("deferred");
            let db = dir.join("sessions.db");
            let mut s = SessionStore::with_backend(Box::new(backend(&db)));
            s.append_turn(Some("s1"), "q1", "a1", None, Vec::new());
            drop(s);
            let reader = backend(&db);
            let snapshot = reader.load_store().expect("snapshot");
            let db2 = db.clone();
            let w = std::thread::spawn(move || {
                let c = rusqlite::Connection::open(&db2).unwrap();
                c.execute_batch("PRAGMA busy_timeout=5000; BEGIN IMMEDIATE;").unwrap();
                c.execute("UPDATE sessions SET title=title WHERE conversation_id='s1'", []).unwrap();
                std::thread::sleep(std::time::Duration::from_millis(300));
                c.execute_batch("COMMIT;").unwrap();
            });
            std::thread::sleep(std::time::Duration::from_millis(100));
            eprintln!("commit_boundary => {:?}", reader.commit_boundary(&snapshot));
            w.join().unwrap();
        }
        // F9: cross-process single-instance lock -> second process silently becomes read-only.
        "hold" => {
            let db = PathBuf::from("/tmp/l3a-ro/sessions.db");
            std::fs::create_dir_all("/tmp/l3a-ro").unwrap();
            let _s = SessionStore::with_backend(Box::new(backend(&db)));
            eprintln!("[hold] store opened (flock held), sleeping 4s");
            std::thread::sleep(std::time::Duration::from_secs(4));
        }
        "write" => {
            let db = PathBuf::from("/tmp/l3a-ro/sessions.db");
            let mut s = SessionStore::with_backend(Box::new(backend(&db)));
            s.append_turn(Some("s1"), "q", "a", None, Vec::new());
            let conn = rusqlite::Connection::open(&db).unwrap();
            let n: i64 = conn
                .query_row("SELECT COUNT(*) FROM sessions WHERE conversation_id='s1'", [], |r| r.get(0))
                .unwrap();
            eprintln!("[write] rows for s1 = {n} (1 == persisted, 0 == silently lost)");
        }
        other => panic!("unknown mode {other}"),
    }
}

